// lane3 generated stage: sampled C/Z Toffoli cuts and swap-park AND holds, bound to the complete pre-tail stream
// (length + SHA3-256). Generated by lane3sig (re-derive with rederive.sh on any stream). Applicator = source_edits format.
use crate::circuit::{Op,OperationType as K};
use sha3::{Digest,Sha3_256};
fn rec(o:&Op)->[u64;7]{[o.kind as u64,o.q_control2.0,o.q_control1.0,o.q_target.0,o.c_target.0,o.c_condition.0,o.r_target.0]}
fn mk(v:&[u64])->Op{let kinds=[K::Neg,K::Register,K::AppendToRegister,K::BitInvert,K::BitStore0,K::BitStore1,K::X,K::Z,K::CX,K::CZ,K::Swap,K::R,K::Hmr,K::CCX,K::CCZ,K::PushCondition,K::PopCondition,K::DebugPrint];let mut o=Op::empty();o.kind=kinds[v[0]as usize];o.q_control2.0=v[1];o.q_control1.0=v[2];o.q_target.0=v[3];o.c_target.0=v[4];o.c_condition.0=v[5];o.r_target.0=v[6];o.validate();o}
pub(super) fn run(v:Vec<Op>)->Vec<Op>{
let mut lines=include_str!("lane3_sigcut.txt").lines();let h:Vec<&str>=lines.next().unwrap().split_whitespace().collect();assert_eq!(v.len(),h[0].parse::<usize>().unwrap(),"lane3_sigcut: stream length");let mut hash=Sha3_256::new();for o in &v{for x in rec(o){hash.update(x.to_le_bytes());}}assert_eq!(format!("{:x}",hash.finalize()),h[1],"lane3_sigcut: complete-stream hash");
let mut rows: Vec<&str> = lines.filter(|l| !l.is_empty()).collect();
rows.push("170536 1 2 12 18446744073709551615 18446744073709551615 12 1573 18446744073709551615 18446744073709551615 10 18446744073709551615 12 1230 18446744073709551615 18446744073709551615 18446744073709551615 4 18446744073709551615 18446744073709551615 18446744073709551615 1573 18446744073709551615 18446744073709551615");
rows.push("691066 1 1 13 788 784 1145 18446744073709551615 18446744073709551615 18446744073709551615 10 18446744073709551615 1230 1145 18446744073709551615 18446744073709551615 18446744073709551615");
rows.sort_by_key(|l| l.split_whitespace().next().unwrap().parse::<usize>().unwrap());
let mut out=Vec::with_capacity(v.len()+1024);let mut at=0;for l in rows{let a:Vec<u64>=l.split_whitespace().map(|s|s.parse().unwrap()).collect();let(i,n,z)=(a[0]as usize,a[1]as usize,a[2]as usize);assert!(i>=at,"lane3_sigcut: unsorted edit");out.extend_from_slice(&v[at..i]);assert_eq!(a.len(),3+7*(n+z));for j in 0..n{assert_eq!(rec(&v[i+j]),a[3+7*j..3+7*j+7]);}for r in a[3+7*n..].chunks(7){out.push(mk(r));}at=i+n;}out.extend_from_slice(&v[at..]);out}
